import{_ as e,o as r,c as o,a2 as a}from"./chunks/framework.E8pQZ6KS.js";const u=JSON.parse('{"title":"Docker","description":"","frontmatter":{},"headers":[],"relativePath":"必学工具/Docker.md","filePath":"必学工具/Docker.md","lastUpdated":1792430298000}'),l={name:"必学工具/Docker.md"};function d(c,t,i,n,s,h){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h1><blockquote><p>轻量级虚拟化容器。学网安的人用它搭靶场、跑工具、隔离环境，几乎每个安全实验平台都基于容器。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li><strong>搭靶场</strong>：DVWA、pikachu 等漏洞环境一条命令启动；</li><li><strong>隔离环境</strong>：分析恶意样本、跑不信任的工具时，容器是常用隔离手段之一（注意：容器并非强隔离，恶意代码分析仍需用专用虚拟机）；</li><li><strong>学习基础设施</strong>：本地跑数据库、中间件、微服务都变得极简单。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><ul><li><strong>镜像（Image）</strong>：只读模板（如 <code>ubuntu:22.04</code>）</li><li><strong>容器（Container）</strong>：镜像的运行实例</li><li><strong>Dockerfile</strong>：描述如何构建镜像</li><li><strong>数据卷（Volume）</strong>：容器间/宿主机持久化数据</li></ul><h2 id="常用命令" tabindex="-1">常用命令 <a class="header-anchor" href="#常用命令" aria-label="Permalink to &quot;常用命令&quot;">​</a></h2><ul><li><code>docker pull &lt;镜像&gt;</code> / <code>docker run -it &lt;镜像&gt; bash</code></li><li><code>docker ps</code> / <code>docker stop &lt;容器&gt;</code> / <code>docker rm &lt;容器&gt;</code></li><li><code>docker build -t &lt;名字&gt; .</code></li><li><code>docker compose up -d</code>（多容器编排，靶场常用）</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://docs.docker.com/" target="_blank" rel="noreferrer">Docker 官方文档</a></td><td>文档</td><td>权威手册</td></tr><tr><td><a href="https://www.runoob.com/docker/docker-tutorial.html" target="_blank" rel="noreferrer">Docker 入门教程（菜鸟教程）</a></td><td>教程</td><td>中文快速上手</td></tr><tr><td><a href="https://labs.play-with-docker.com/" target="_blank" rel="noreferrer">Play with Docker</a></td><td>在线环境</td><td>浏览器里练 Docker</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>大二开始用 Docker 搭课程实验环境，能省大量「装环境」的时间；</li><li>学会写 Dockerfile 和 docker-compose.yml，后面玩靶场会频繁用到。</li></ul>',12)])])}const b=e(l,[["render",d]]);export{u as __pageData,b as default};
